def fixture(cmd,main,basics):
 from collections import Counter
 c=Counter(main);left=100-len(cmd)-sum(c.values())
 for n in range(left):c[basics[n%len(basics)]]+=1
 return {'main':dict(c),'commanders':dict(Counter(cmd))}
